package ledger;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** Reads journal files into transactions, collecting every syntax error rather than throwing. */
final class Parser {

    private final List<Transaction> transactions = new ArrayList<>();
    private final List<LedgerError> errors = new ArrayList<>();
    private final Set<Path> open = new LinkedHashSet<>();

    private Parser() {
    }

    static Journal parse(Path file) throws IOException {
        Parser parser = new Parser();
        parser.read(file);
        return new Journal(List.copyOf(parser.transactions), List.copyOf(parser.errors));
    }

    private void read(Path file) throws IOException {
        List<String> lines = Files.readAllLines(file);

        LocalDate date = null;
        String payee = null;
        List<Posting> postings = null;
        int headerLine = 0;
        boolean skipping = false;

        for (int i = 0; i < lines.size(); i++) {
            int lineNo = i + 1;
            String line = stripComment(lines.get(i));
            boolean indented = !line.isEmpty() && Character.isWhitespace(line.charAt(0));
            String content = line.strip();

            if (content.isEmpty()) {
                continue;
            }

            if (indented) {
                if (skipping) {
                    continue;
                }
                if (postings == null) {
                    errors.add(new LedgerError(file, lineNo, "posting outside of a transaction"));
                    continue;
                }
                Posting posting = parsePosting(file, content, lineNo);
                if (posting != null) {
                    postings.add(posting);
                }
                continue;
            }

            if (postings != null) {
                transactions.add(new Transaction(date, payee, List.copyOf(postings), file, headerLine));
                postings = null;
            }
            skipping = false;

            if (content.startsWith("include ") || content.equals("include")) {
                include(file, content, lineNo);
                skipping = true;
                continue;
            }

            int space = content.indexOf(' ');
            if (space < 0) {
                errors.add(new LedgerError(file, lineNo, "expected a date followed by a payee: " + content));
                skipping = true;
                continue;
            }
            try {
                date = LocalDate.parse(content.substring(0, space));
            } catch (DateTimeParseException e) {
                errors.add(new LedgerError(file, lineNo,
                        "not a date in YYYY-MM-DD form: " + content.substring(0, space)));
                skipping = true;
                continue;
            }
            payee = content.substring(space + 1).strip();
            if (payee.isEmpty()) {
                errors.add(new LedgerError(file, lineNo, "a transaction needs a payee after its date"));
                skipping = true;
                continue;
            }
            postings = new ArrayList<>();
            headerLine = lineNo;
        }

        if (postings != null) {
            transactions.add(new Transaction(date, payee, List.copyOf(postings), file, headerLine));
        }
    }

    private void include(Path from, String content, int lineNo) throws IOException {
        String name = content.substring("include".length()).strip();
        if (name.isEmpty()) {
            errors.add(new LedgerError(from, lineNo, "include needs a file name"));
            return;
        }
        Path parent = from.toAbsolutePath().getParent();
        Path target = (parent == null ? Path.of(name) : parent.resolve(name)).normalize();
        if (!Files.isReadable(target)) {
            errors.add(new LedgerError(from, lineNo, "cannot read included file: " + name));
            return;
        }
        if (!open.add(target)) {
            errors.add(new LedgerError(from, lineNo, "include cycle: " + name + " is already being read"));
            return;
        }
        read(target);
        open.remove(target);
    }

    /** A `;` starts a comment that runs to the end of the line. */
    private static String stripComment(String line) {
        int at = line.indexOf(';');
        return at < 0 ? line : line.substring(0, at);
    }

    private Posting parsePosting(Path file, String content, int lineNo) {
        String[] parts = content.split("\\s+", 2);
        String account = parts[0];
        if (parts.length == 1) {
            return new Posting(account, null, lineNo);
        }
        String[] amount = parts[1].strip().split("\\s+");
        if (amount.length != 2) {
            errors.add(new LedgerError(file, lineNo, "expected `<amount> <currency>` but found: " + parts[1].strip()));
            return null;
        }
        try {
            return new Posting(account, new Amount(new BigDecimal(amount[0]), amount[1]), lineNo);
        } catch (NumberFormatException e) {
            errors.add(new LedgerError(file, lineNo, "not a number: " + amount[0]));
            return null;
        }
    }
}
