package ledger;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Fills in the one amount a transaction may omit and reports the transactions whose postings do
 * not sum to zero. Currencies are balanced independently and never converted into one another.
 */
final class Balancer {

    private Balancer() {
    }

    static Journal resolve(Journal journal) {
        List<Transaction> resolved = new ArrayList<>(journal.transactions().size());
        List<LedgerError> errors = new ArrayList<>(journal.errors());

        for (Transaction tx : journal.transactions()) {
            resolved.add(resolve(tx, errors));
        }
        return new Journal(List.copyOf(resolved), List.copyOf(errors));
    }

    private static Transaction resolve(Transaction tx, List<LedgerError> errors) {
        List<Posting> postings = tx.postings();
        if (postings.isEmpty()) {
            errors.add(error(tx, "transaction has no postings"));
            return tx;
        }

        List<Posting> elided = postings.stream().filter(p -> p.amount() == null).toList();
        if (elided.size() > 1) {
            errors.add(error(tx, "more than one posting omits its amount (lines "
                    + elided.stream().map(p -> String.valueOf(p.line())).collect(Collectors.joining(", ")) + ")"));
            return tx;
        }

        Map<String, BigDecimal> residual = residual(postings);

        if (elided.isEmpty()) {
            if (!residual.isEmpty()) {
                errors.add(error(tx, "transaction does not balance: " + describe(residual) + " left over"));
            }
            return tx;
        }

        if (residual.size() > 1) {
            errors.add(error(tx, "cannot infer the amount on line " + elided.get(0).line()
                    + ": " + residual.size() + " currencies are unbalanced (" + describe(residual) + ")"));
            return tx;
        }

        Amount inferred = inferred(residual, postings);
        if (inferred == null) {
            errors.add(error(tx, "cannot infer the amount on line " + elided.get(0).line()
                    + ": the transaction has no other amount to infer it from"));
            return tx;
        }

        List<Posting> filled = postings.stream()
                .map(p -> p.amount() == null ? new Posting(p.account(), inferred, p.line()) : p)
                .toList();
        return new Transaction(tx.date(), tx.payee(), filled, tx.file(), tx.line());
    }

    /** The non-zero sum per currency, in the order the currencies first appear. */
    private static Map<String, BigDecimal> residual(List<Posting> postings) {
        Map<String, BigDecimal> sums = new LinkedHashMap<>();
        for (Posting posting : postings) {
            if (posting.amount() != null) {
                sums.merge(posting.amount().currency(), posting.amount().value(), BigDecimal::add);
            }
        }
        sums.values().removeIf(value -> value.signum() == 0);
        return sums;
    }

    private static Amount inferred(Map<String, BigDecimal> residual, List<Posting> postings) {
        if (residual.size() == 1) {
            Map.Entry<String, BigDecimal> only = residual.entrySet().iterator().next();
            return new Amount(only.getValue().negate(), only.getKey());
        }
        return postings.stream()
                .filter(p -> p.amount() != null)
                .findFirst()
                .map(p -> new Amount(BigDecimal.ZERO, p.amount().currency()))
                .orElse(null);
    }

    private static String describe(Map<String, BigDecimal> residual) {
        return residual.entrySet().stream()
                .map(e -> new Amount(e.getValue(), e.getKey()).format())
                .collect(Collectors.joining(", "));
    }

    private static LedgerError error(Transaction tx, String message) {
        return new LedgerError(tx.file(), tx.line(), message);
    }
}
