package ledger;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Renders account balances as an indented tree, each account totalling its own subtree. */
final class Balance {

    private Balance() {
    }

    /** @param depth the deepest account level to show, or 0 for every level. */
    static String report(Journal journal, int depth) {
        Map<String, Map<String, BigDecimal>> totals = totals(journal, depth);

        List<Row> rows = new ArrayList<>();
        for (Map.Entry<String, Map<String, BigDecimal>> account : totals.entrySet()) {
            String[] segments = account.getKey().split(":");
            String name = "  ".repeat(segments.length - 1) + segments[segments.length - 1];
            rows.add(new Row(name, account.getValue()));
        }
        return render(rows);
    }

    /** Every account and every parent of one, each holding the sum of its whole subtree. */
    private static Map<String, Map<String, BigDecimal>> totals(Journal journal, int depth) {
        Map<String, Map<String, BigDecimal>> totals = new TreeMap<>();
        for (Transaction tx : journal.transactions()) {
            for (Posting posting : tx.postings()) {
                if (posting.amount() == null) {
                    continue;
                }
                String[] segments = posting.account().split(":");
                int levels = depth > 0 ? Math.min(depth, segments.length) : segments.length;
                StringBuilder path = new StringBuilder();
                for (int level = 0; level < levels; level++) {
                    path.append(level == 0 ? "" : ":").append(segments[level]);
                    totals.computeIfAbsent(path.toString(), key -> new TreeMap<>())
                            .merge(posting.amount().currency(), posting.amount().value(), BigDecimal::add);
                }
            }
        }
        return totals;
    }

    private static String render(List<Row> rows) {
        int nameWidth = 0;
        int valueWidth = 0;
        for (Row row : rows) {
            nameWidth = Math.max(nameWidth, row.name().length());
            for (BigDecimal value : row.amounts().values()) {
                valueWidth = Math.max(valueWidth, value.toPlainString().length());
            }
        }

        StringBuilder out = new StringBuilder();
        for (Row row : rows) {
            String name = row.name();
            for (Map.Entry<String, BigDecimal> amount : row.amounts().entrySet()) {
                out.append(pad(name, nameWidth))
                        .append("  ")
                        .append(alignRight(amount.getValue().toPlainString(), valueWidth))
                        .append(' ')
                        .append(amount.getKey())
                        .append('\n');
                name = "";
            }
        }
        return out.toString();
    }

    private static String pad(String text, int width) {
        return text + " ".repeat(width - text.length());
    }

    private static String alignRight(String text, int width) {
        return " ".repeat(width - text.length()) + text;
    }

    private record Row(String name, Map<String, BigDecimal> amounts) {
    }
}
