package ledger;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** Lists postings in journal order, optionally narrowed to an account or a date range. */
final class Register {

    private Register() {
    }

    /** Every filter is optional; a null one matches everything. */
    static String report(Journal journal, String account, LocalDate since, LocalDate until) {
        List<Row> rows = new ArrayList<>();

        for (Transaction tx : journal.transactions()) {
            if (since != null && tx.date().isBefore(since)) {
                continue;
            }
            if (until != null && tx.date().isAfter(until)) {
                continue;
            }
            String header = tx.date() + " " + tx.payee();
            for (Posting posting : tx.postings()) {
                if (account != null && !posting.account().contains(account)) {
                    continue;
                }
                Amount amount = posting.amount();
                rows.add(new Row(header, posting.account(),
                        amount == null ? "" : amount.value().toPlainString(),
                        amount == null ? "" : amount.currency()));
                header = "";
            }
        }
        return render(rows);
    }

    private static String render(List<Row> rows) {
        int headerWidth = 0;
        int accountWidth = 0;
        int valueWidth = 0;
        for (Row row : rows) {
            headerWidth = Math.max(headerWidth, row.header().length());
            accountWidth = Math.max(accountWidth, row.account().length());
            valueWidth = Math.max(valueWidth, row.value().length());
        }

        StringBuilder out = new StringBuilder();
        for (Row row : rows) {
            out.append(pad(row.header(), headerWidth))
                    .append("  ")
                    .append(pad(row.account(), accountWidth))
                    .append("  ")
                    .append(alignRight(row.value(), valueWidth))
                    .append(' ')
                    .append(row.currency())
                    .append('\n');
        }
        return out.toString();
    }

    private static String pad(String text, int width) {
        return text + " ".repeat(width - text.length());
    }

    private static String alignRight(String text, int width) {
        return " ".repeat(width - text.length()) + text;
    }

    private record Row(String header, String account, String value, String currency) {
    }
