package ledger;

import java.io.IOException;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;

/** The `ledger` command line: validate, balance and register over a journal file. */
public final class Main {

    private static final String USAGE = """
            usage:
              ledger validate <file>
              ledger balance  <file> [--depth N]
              ledger register <file> [--account NAME] [--since YYYY-MM-DD] [--until YYYY-MM-DD]""";

    private static final int OK = 0;
    private static final int PROBLEMS_FOUND = 1;
    private static final int BAD_USAGE = 2;

    private Main() {
    }

    public static void main(String[] args) {
        System.exit(run(args, System.out, System.err));
    }

    /** @return the process exit code: 0 clean, 1 the journal has problems, 2 the command line does. */
    static int run(String[] args, PrintStream out, PrintStream err) {
        if (args.length == 0) {
            err.println(USAGE);
            return BAD_USAGE;
        }
        String command = args[0];
        if (!command.equals("validate") && !command.equals("balance") && !command.equals("register")) {
            err.println("ledger: unknown command: " + command);
            err.println(USAGE);
            return BAD_USAGE;
        }
        if (args.length < 2) {
            err.println("ledger: " + command + " needs a journal file");
            err.println(USAGE);
            return BAD_USAGE;
        }

        Path file = Path.of(args[1]);
        Options options = new Options();
        try {
            options.read(args, command);
        } catch (BadUsage e) {
            err.println("ledger: " + e.getMessage());
            return BAD_USAGE;
        }

        if (!Files.isReadable(file)) {
            err.println("ledger: cannot read " + file + ": no such file");
            return BAD_USAGE;
        }

        Journal journal;
        try {
            journal = Balancer.resolve(Parser.parse(file));
        } catch (IOException e) {
            err.println("ledger: cannot read " + file + ": " + e.getMessage());
            return BAD_USAGE;
        }

        if (command.equals("validate")) {
            journal.errors().forEach(out::println);
            return journal.errors().isEmpty() ? OK : PROBLEMS_FOUND;
        }

        journal.errors().forEach(err::println);
        out.print(command.equals("balance")
                ? Balance.report(journal, options.depth)
                : Register.report(journal, options.account, options.since, options.until));
        return journal.errors().isEmpty() ? OK : PROBLEMS_FOUND;
    }

    /** The options each command accepts; an unset one keeps its neutral default. */
    private static final class Options {
        private int depth;
        private String account;
        private LocalDate since;
        private LocalDate until;

        private void read(String[] args, String command) throws BadUsage {
            for (int i = 2; i < args.length; i++) {
                String flag = args[i];
                switch (flag) {
                    case "--depth" -> depth = positive(flag, value(args, ++i, flag), command, "balance");
                    case "--account" -> account = text(value(args, ++i, flag), command, flag, "register");
                    case "--since" -> since = date(flag, value(args, ++i, flag), command, "register");
                    case "--until" -> until = date(flag, value(args, ++i, flag), command, "register");
                    default -> throw new BadUsage(command + " does not take " + flag);
                }
            }
        }

        private static String value(String[] args, int at, String flag) throws BadUsage {
            if (at >= args.length) {
                throw new BadUsage(flag + " needs a value");
            }
            return args[at];
        }

        private static String text(String value, String command, String flag, String allowedOn) throws BadUsage {
            if (!command.equals(allowedOn)) {
                throw new BadUsage(command + " does not take " + flag);
            }
            return value;
        }

        private static int positive(String flag, String value, String command, String allowedOn) throws BadUsage {
            text(value, command, flag, allowedOn);
            int depth;
            try {
                depth = Integer.parseInt(value);
            } catch (NumberFormatException e) {
                throw new BadUsage(flag + " needs a whole number, but got: " + value);
            }
            if (depth < 1) {
                throw new BadUsage(flag + " needs a number of at least 1, but got: " + value);
            }
            return depth;
        }

        private static LocalDate date(String flag, String value, String command, String allowedOn) throws BadUsage {
            text(value, command, flag, allowedOn);
            try {
                return LocalDate.parse(value);
            } catch (DateTimeParseException e) {
                throw new BadUsage(flag + " needs a date in YYYY-MM-DD form, but got: " + value);
            }
        }
    }

    private static final class BadUsage extends Exception {
        private BadUsage(String message) {
            super(message);
        }
    }
}
